    /**
     * Tests getting all ProductionCertificates.
     *
     * @return    Collection
     */
    public List<ProductionCertificate> testGetAll() throws Throwable {
    LOGGER.info( "ProductionCertificateTest:testGetAll() - Retrieving Collection of ProductionCertificates:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ProductionCertificate : " );
    List<ProductionCertificate> collection  = null;

    try {
        // call the static get method on the ProductionCertificateService
        collection = service.getAllProductionCertificate();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ProductionCertificate currEntity  = null;
            Iterator<ProductionCertificate> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getProductionCertificateId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

